const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define Seattle geometry
  const seattle = ee.Geometry.Point([-122.33, 47.61]);
  const buffer = seattle.buffer(50000); // 50km buffer to ensure coverage

  // Define date ranges for Sep-Nov
  const dates = {
    2019: { start: '2019-09-01', end: '2019-11-30' },
    2020: { start: '2020-09-01', end: '2020-11-30' },
    2021: { start: '2021-09-01', end: '2021-11-30' }
  };

  // Function to calculate total precipitation
  async function getPrecipitation(year) {
    const col = ee.ImageCollection('NOAA/PERSIANN-CDR')
      .filterDate(dates[year].start, dates[year].end)
      .filterBounds(buffer);

    const size = col.size().getInfo();
    if (size === 0) {
      console.log(`${year}: No data found.`);
      return null;
    }

    // Sum all daily precipitation
    const totalPrecip = col.select('precipitation').sum();

    // Calculate mean over the buffer region
    const stats = totalPrecip.reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: buffer,
      scale: 5000,
      maxPixels: 1e9
    }).getInfo();

    const precipValue = stats['precipitation'];

    // Check for valid pixels
    const pixelCount = totalPrecip.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: buffer,
      scale: 5000,
      maxPixels: 1e9
    }).getInfo();

    const count = pixelCount['precipitation'];

    console.log(`${year}: Images=${size}, Precip=${precipValue !== null ? precipValue.toFixed(1) : 'null'}mm, ValidPixels=${count}`);

    if (count === 0) {
      console.log(`${year}: No valid pixels after processing.`);
      return null;
    }

    if (precipValue === null || isNaN(precipValue)) {
      console.log(`${year}: Invalid precipitation value.`);
      return null;
    }

    return precipValue;
  }

  // Get precipitation for all three years
  const precip2019 = await getPrecipitation(2019);
  const precip2020 = await getPrecipitation(2020);
  const precip2021 = await getPrecipitation(2021);

  // Validate results
  if (precip2019 === null || precip2020 === null || precip2021 === null) {
    console.log('Result: <answer>C1</answer>');
    return;
  }

  // Check if 2021 is larger than both 2020 and 2019
  const is2021Larger = (precip2021 > precip2020) && (precip2021 > precip2019);

  console.log(`Summary: 2019=${precip2019.toFixed(1)}mm, 2020=${precip2020.toFixed(1)}mm, 2021=${precip2021.toFixed(1)}mm`);

  if (is2021Larger) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
